Q: Lazy Loading Images in Next.js and/or in other forms of React server-side rendering A: <p>I think the way you see it is right, for client side code (like lazyload) I often use the <code>componentDidMount</code> lifecycle methods.</p>
<p>A <code>HOC</code> like this should do the trick.</p>
<pre><code>function lazyLoadImages(selector = 'img') {
    function createObserver() {
        const elements = document.querySelectorAll(selector);
        const observer = new window.IntersectionObserver((entries, observerChild) =&gt; {
            entries.forEach((entry) =&gt; {
                if (entry.isIntersecting &amp;&amp; entry.target.getAttribute('data-src')) {
                    entry.target.src = entry.target.getAttribute('data-src');
                    entry.target.removeAttribute('data-src');
                    observerChild.unobserve(entry.target);
                }
            });
        }, {});

        Array.prototype.map.call(elements, function(item) {
            observer.observe(item);
        });
    }

    if (!('IntersectionObserver' in window)) {
        const polyfill = document.createElement('script');
        polyfill.src = 'https://polyfill.io/v2/polyfill.min.js?features=IntersectionObserver';
        document.head.appendChild(polyfill);

        polyfill.onload = () =&gt; {
            createObserver();
        };
        return;
    }

    createObserver();
}

const LazyLoadHOC = (Page) =&gt; {
    return class extends React.Component {
        static getInitialProps(ctx) {
            if(Page.getInitialProps)
                return Page.getInitialProps(ctx);
        }

        componentDidMount() {
           lazyLoadImages('img');
        }

        render() {
            return &lt;Page {...this.props}/&gt;
        }

    }
}
</code></pre>
<p>Now you can wrap your pages with the <code>LazyLoadHOC</code> and replace <code>src</code> with <code>data-src</code> for all images you want to lazy load.</p>
